using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class RemainingFinalImport {public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying)throw new Exception("Edit required");if(s.isDirty){string b=Path.Combine(Path.GetTempPath(),"AfterSeconds_FinalImport_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity");if(!EditorSceneManager.SaveScene(s,b,true))throw new Exception("Backup failed");EditorSceneManager.SaveScene(s);}foreach(string n in new[]{"VB_Shaft","VL_Shaft","VL_Hoist","VL_Floor"})AssetDatabase.ImportAsset("Assets/Afrer_Seconds/05.Model/Environment/B5/RD_"+n+".fbx",ImportAssetOptions.ForceSynchronousImport);string record="Assets/Afrer_Seconds/06.Data/AssetSources/B5_RemainingDomes_20261108.json";if(File.Exists(record))AssetDatabase.ImportAsset(record,ImportAssetOptions.ForceSynchronousImport);AssetDatabase.SaveAssets();return new{scene=s.path,dirty=s.isDirty,imports=4};}}
